@'
import json
import urllib.error
import urllib.request

class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None

url = "https://my.opentext.com/api/web/feed/product"
request = urllib.request.Request(url, headers={"User-Agent": "ProductSupportAgent-Phase0-ReadOnlyProbe/1.0"}, method="GET")
opener = urllib.request.build_opener(NoRedirect)
try:
    with opener.open(request, timeout=15) as response:
        raw = response.read(16385)
        content_type = response.headers.get_content_type()
        print(f"status={response.status}; content_type={content_type}; bytes_read={len(raw)}; truncated={len(raw) > 16384}")
        if len(raw) <= 16384:
            try:
                value = json.loads(raw)
                if isinstance(value, list):
                    print(f"json_root=array; item_count={len(value)}")
                    if value and isinstance(value[0], dict):
                        print("first_item_keys=" + ",".join(list(value[0])[:12]))
                elif isinstance(value, dict):
                    print("json_root=object; keys=" + ",".join(list(value)[:12]))
                    for key, child in value.items():
                        if isinstance(child, list):
                            print(f"array_property={key}; item_count={len(child)}")
                            if child and isinstance(child[0], dict):
                                print("first_item_keys=" + ",".join(list(child[0])[:12]))
                            break
                else:
                    print("json_root=" + type(value).__name__)
            except (json.JSONDecodeError, UnicodeDecodeError) as exc:
                print(f"json_parse_failed={type(exc).__name__}; line={getattr(exc, 'lineno', 'n/a')}; column={getattr(exc, 'colno', 'n/a')}")
except urllib.error.HTTPError as exc:
    print(f"http_status={exc.code}; redirect_not_followed={300 <= exc.code < 400}")
except Exception as exc:
    print(f"request_failed={type(exc).__name__}")
'@ | python -

